class Solution {
  public int minTimeToReach(int[][] moveTime) {
    int n = moveTime.length, m = moveTime[0].length;
    int[][] dist = new int[n][m];
    for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    dist[0][0] = 0;
    pq.offer(new int[] {0, 0, 0});
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    while (!pq.isEmpty()) {
      int[] cur = pq.poll();
      if (cur[0] > dist[cur[1]][cur[2]]) continue;
      if (cur[1] == n - 1 && cur[2] == m - 1) return cur[0];
      // moves alternate 1s, 2s, ...; the parity of the cell tells which move comes next
      int cost = (cur[1] + cur[2]) % 2 == 0 ? 1 : 2;
      for (int d = 0; d < 4; d++) {
        int r = cur[1] + dr[d], c = cur[2] + dc[d];
        if (r < 0 || c < 0 || r >= n || c >= m) continue;
        int arrive = Math.max(cur[0], moveTime[r][c]) + cost;
        if (arrive < dist[r][c]) {
          dist[r][c] = arrive;
          pq.offer(new int[] {arrive, r, c});
        }
      }
    }
    return -1;
  }
}
